// HasUser applies the HasEdge predicate on the "user" edge.
func HasUser() predicate.NPC {
	return predicate.NPC(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, UserTable, UserColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUserWith applies the HasEdge predicate on the "user" edge with a given conditions (other predicates).
func HasUserWith(preds ...predicate.User) predicate.NPC {
	return predicate.NPC(func(s *sql.Selector) {
		step := newUserStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasCharacterNpcs applies the HasEdge predicate on the "character_npcs" edge.
func HasCharacterNpcs() predicate.NPC {
	return predicate.NPC(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, CharacterNpcsTable, CharacterNpcsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCharacterNpcsWith applies the HasEdge predicate on the "character_npcs" edge with a given conditions (other predicates).
func HasCharacterNpcsWith(preds ...predicate.CharacterNPC) predicate.NPC {
	return predicate.NPC(func(s *sql.Selector) {
		step := newCharacterNpcsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.NPC) predicate.NPC {
	return predicate.NPC(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.NPC) predicate.NPC {
	return predicate.NPC(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.NPC) predicate.NPC {
	return predicate.NPC(sql.NotPredicates(p))
}
